{
  "name": "SHFQA 扫频软件模块",
  "name_en": "SHFQA Sweeper Software Module",
  "manufacturer": "Zurich Instruments",
  "description": "这是一个面向 Zurich Instruments SHFQA 的非物理扫频软件模块，用于配置频率范围、射频收发、平均、触发和脉冲包络等参数，并执行扫频、返回结果和绘图。它常用于量子器件、谐振器或频谱响应测量流程中的自动化扫描。",
  "description_en": "This is a non-physical sweeper software module for the Zurich Instruments SHFQA. It configures sweep range, RF I/O, averaging, trigger, and pulse envelope settings, then runs sweeps, returns results, and plots data. It is commonly used in automated measurements of quantum devices, resonators, or frequency-response experiments.",
  "actions": [
    {
      "action_name": "auto-run",
      "description": "执行按当前设置配置的频率扫频测量。",
      "description_en": "Run a frequency sweep using the current settings."
    },
    {
      "action_name": "auto-get_result",
      "description": "获取上一次扫频的测量数据。",
      "description_en": "get measurement data of the last sweep"
    },
    {
      "action_name": "auto-plot",
      "description": "绘制上一次扫频的功率-频率曲线。",
      "description_en": "Plot power versus frequency for the last sweep."
    },
    {
      "action_name": "auto-get_offset_freq_vector",
      "description": "获取频率点向量。",
      "description_en": "get vector of frequency points"
    }
  ],
  "tag_hints": [
    "SHFQA",
    "frequency sweep",
    "spectroscopy",
    "quantum measurement",
    "RF sweep configuration",
    "sweep result plotting",
    "Zurich Instruments"
  ]
}

